}

public int findMinFibonacciNumbers(int k) {
    int[] fib = {1, 1};
    int i = 0;
    while (fib[i] <= k) {
        fib[i + 1] = fib[i] + fib[i - 1];
        i++;
    }
    return findMinFibonacciNumbersRecursive(k, fib, i - 1);
}

private int findMinFibonacciNumbersRecursive(int k, int[] fib, int len) {
    if (k == 0) {
        return 0;
    }
    if (fib[len] > k) {
        return findMinFibonacciNumbersRecursive(k, fib, len - 1);
    }
    return Math.min(1 + findMinFibonacciNumbersRecursive(k - fib[len], fib, len), findMinFibonacciNumbersRecursive(k, fib, len - 1));
}

