public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length, n = mat[0].length, maxLength = 0;
    if (n < 2) {
        for (int i = 0; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (mat[i][j] == 1 && mat[i][j-1] == 1) {
                    maxLength = Math.max(maxLength, 2);
                }
            }
        }
        return maxLength;
    }

    // Create direction arrays for left, right, up, and down
    int[][] dirs = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

    for (int i = 0; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (mat[i][j] == 1 && (i == 0 || mat[i-1][j] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[0]));
            }
            if (mat[i][j] == 1 && (i == m-1 || mat[i+1][j] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[1]));
            }
            if (mat[i][j] == 1 && (j == 0 || mat[i][j-1] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[2]));
            }
            if (mat[i][j] == 1 && (j == n-1 || mat[i][j+1] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[3]));
            }
        }
    }

    return maxLength;
}

private static int dfs(int[][] mat, int i, int j, int[] dir) {
    int result = 1;
    int x = i, y = j;
    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
        result++;
        x += dir[0];
        y += dir[1];
    }

    x = i;
    y = j;
    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
        result++;
        x -= dir[0];
        y -= dir[1];
    }

    return result;
}

public static String addThousandSeparator(int n) {
