    for (int i = length - 2; i >= 0; i--) {
        if (isValid(A, i)) {
            int prev = A[i + 1];
            A[i + 1] = A[i];
            A[i] = prev;
            count += squarePermutations(A);
            A[i] = prev;
            A[i + 1] = prev;
        }
    }
    return count;
}

