public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[i] < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    while (!stack.isEmpty()) {
        int height = heights[stack.pop()];
        int width = stack.isEmpty() ? heights.length : heights.length - stack.peek() - 1;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int k = 0;
    int i = 0;
    int j = 0;

    while (k < rows * cols) {
        result[k++] = mat[i][j];
        if ((i + j) % 2 == 0) {
            // Move diagonally to the right if sum is even
            j += 1;
            if (j == cols) {
                i += 1;
                j -= 1;
            }
        } else {
            // Move diagonally to the left if sum is odd
            i += 1;
            if (i == rows) {
                j += 1;
                i -= 1;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a character array for easy manipulation
    char[] digits = Integer.toString(n).toCharArray();

    // Find the index of the first digit from the right that is less than the digit on its left
    int i = -1;
    for (int j = digits.length - 2; j >= 0; j--) {
        if (digits[j] < digits[j + 1]) {
            i = j;
            break;
        }
    }

    if (i == -1) {
        // If no such pair is found, it's not possible to form a larger integer
        return -1;
    }

    // Find the smallest digit on the right that is larger than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the digits i and j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits to the right of index i in ascending order
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the character array back to an integer
    return Integer.parseInt(new String(digits));
}

