            int left = 0;
            int right = (n + 1) / 2;
            while (left < 10 && right >= 0) {
                result.add(String.valueOf(left) + new StringBuilder().reverse(String.valueOf(right)).toString());
                left++;
                right--;
            }
        }
        return result;
    }

private static boolean isSymmetric(String left, String right) {
        int length = left.length();
        for (int i = 0; i < length / 2; i++) {
            if (left.charAt(i) != right.charAt(length - i - 1)) {
                return false;
            }
        }
        return true;
    }

public static boolean isBoomerang(int[][] points) {
    int[] a = points[0];
    int[] b = points[1];
    int[] c = points[2];

    // Check if any of the conditions indicates the points are collinear
    if ((a[0] * b[1] + b[0] * c[1] + c[0] * a[1]) == (a[0] * c[1] + b[0] * a[1] + c[0] * b[1]))
        return false;

    // Check if the points do not form a right triangle
    return b[0] * c[1] != a[0] * b[1];
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int two = 2, three = 3, five = 5;
    int i = 2;
    while (i <= n) {
        int min = Math.min(dp[two] * 2, Math.min(dp[three] * 3, dp[five] * 5));
        dp[i] = min;
        if (min == dp[two] * 2) two++;
        if (min == dp[three] * 3) three++;
        if (min == dp[five] * 5) five++;
        i++;
    }
    return dp[n];
}

public static int calculateEnergy(String s) {
    int maxLength = 0;
    int currentLength = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
        }
    }

    maxLength = Math.max(maxLength, currentLength);

    return maxLength;
}

public List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;

    // Helper function to create the next number in lexicographical order
    private int next(int num) {
        if (num == 9) return 0;
        return num * 10;
    }

    // Use a priority queue to explore numbers in lexicographical order
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    queue.offer(1);

    int current = 1;
    while (!queue.isEmpty() && current <= n) {
        current = queue.poll();
        result.add(current);

        int nextValue = next(current);
        if (nextValue <= n) {
            queue.offer(nextValue);
        }
    }

    return result;
}

private int next(int num) {
        if (num == 9) return 0;
        return num * 10;
    }

public static int calculateUniqueSum(int[] nums) {
    HashSet<Integer> uniqueElements = new HashSet<>();

    // Add each element to the set to remove duplicates
    for (int num : nums) {
        uniqueElements.add(num);
    }

    // Calculate the sum of unique elements
    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    StringBuilder sb = new StringBuilder();
    for (String word : s.split(" ")) {
        // Reverse each word and append to the result string
        sb.append(new StringBuilder(word).reverse().toString() + " ");
    }
    // Remove the trailing space
    return sb.toString().trim();
}
